from nltk.tokenize import word_tokenize as tokenize
import numpy as np

#  Preprocess text to sequence of ngrams
def split_sentences(text:str) -> list: # Splits text to reolics by roles
    splited_text = text.split("<EOS>")

    seq = []

    for part in splited_text:
        if "<" in part and "> " in part:
            role, text = part.split("> ", 1)   

            role = role.replace(" ", "") + ">"

            seq.append((role, text, "<EOS>"))
        else:
            seq.append((None, part, None))

    return seq

def word_tokenize(text: str) -> list: # Makes tokens from row text 
    text = text.lower()

    word_tokens = tokenize(text, "russian")

    return word_tokens

def make_ngrams(word_tokens: list, n: int = 3) -> list: # Makes ngrams from list of tokens
    ngrams = []
    
    for word_token in word_tokens:
        token = f"<{word_token}>"
        token_len = len(token)
        
        ngrams.extend([token[i:i+n] for i in range(token_len - n + 1)])
    
    return ngrams

def preprocess(text:str, n:int = 3) -> list: # Automaticaly preprocess text to ngram sequence 
    splited_sentences = split_sentences(text)

    seq = []

    for role, text, eos in splited_sentences:
        word_tokens = word_tokenize(text)
        
        ngrams = make_ngrams(word_tokens, n)
        if role:
            seq.append(role)

        seq.extend(ngrams)

        if eos:
            seq.append(eos)

    return seq

# Encodes and decodes sequesnce by vocabulary
def lookup_token(id:int, vocabulary:dict): # Finds token in vocabulary by id
    try:
        return vocabulary[id]
    except KeyError:
        return vocabulary[1]

def lookup_token_id(token:str, vocabulary:dict): # Finds id in vocabulary by token
    try:
        return vocabulary[token]
    except KeyError:
        return vocabulary['<UNK>']

def seq_to_ids(token_seq:list, vocabulary:dict): # Processes token sequence to id sequence 
    if vocabulary.get(0):
        vocabulary = {v: k for k, v in vocabulary.items()}

    id_seq = [lookup_token_id(token, vocabulary) for token in token_seq]

    return id_seq

def ids_to_seq(id_seq:list, vocabulary:dict): # Processes id sequence to token sequence
    if not vocabulary.get(0):
        vocabulary = {v: k for k, v in vocabulary.items()}

    token_seq = [lookup_token(id, vocabulary) for id in id_seq]

    return token_seq

