def make_padding_mask(seq, seq_len:int):
    padding_mask = [1 for item in seq]

    for i in range(seq_len - len(seq)):
        padding_mask.append(0)
        
    padding_mask = np.array(padding_mask)
    padding_mask  = padding_mask[None, None, :]

    return padding_mask 

